/**
 * Automated Test Suite for CardioCoreEdge Phase 13B:
 * Frontend Protocol v2 Decoder, CSRF Helper, API Client, and Feature Flag Isolation
 */

import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

// Read fixtures generated by backend
const fixturesPath = path.resolve(__dirname, "../tests_fixtures.json");
const fixtures = JSON.parse(fs.readFileSync(fixturesPath, "utf-8"));

function base64ToUint8Array(base64) {
  const buf = Buffer.from(base64, "base64");
  return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
}

// Dynamically import compiled/transpiled or direct TS protocol modules
// Since Node 24 supports TS syntax:
const protocolV2 = await import("../src/lib/telemetry/protocol-v2.ts");
const protocolV1 = await import("../src/lib/telemetry/protocol.ts");
const csrfModule = await import("../src/lib/api/csrf.ts");
const backendConfig = await import("../src/lib/api/backend-config.ts");

console.log("================================================================================");
console.log("CardioCoreEdge Phase 13B: Frontend Automated Test Suite");
console.log("================================================================================");

let passedTests = 0;
let failedTests = 0;

async function runTest(name, fn) {
  try {
    await fn();
    console.log(`[PASS] ${name}`);
    passedTests++;
  } catch (err) {
    console.error(`[FAIL] ${name}:`, err);
    failedTests++;
  }
}

// ------------------------------------------------------------------------------
// Test Group 1: Backend Interoperability & Decoders
// ------------------------------------------------------------------------------

await runTest("Decode 1-Lead Raw Synthetic Frame from Backend Encoder", async () => {
  const f = fixtures.single_lead_raw;
  const bytes = base64ToUint8Array(f.bytes_b64);
  const frame = await protocolV2.unpackMultiChannelFrame(bytes);

  assert.equal(frame.header.magic, 0xCC);
  assert.equal(frame.header.version, 0x02);
  assert.equal(frame.header.activeLeadsMask, protocolV2.SINGLE_LEAD_II_MASK);
  assert.equal(frame.header.activeChannelCount, 1);
  assert.deepEqual(frame.header.activeLeadNames, ["Lead-II"]);
  assert.equal(frame.header.sampleCount, 6);
  assert.deepEqual(frame.channels["Lead-II"], f.expected_samples[0]);
});

await runTest("Decode 3-Lead Raw Synthetic Frame from Backend Encoder", async () => {
  const f = fixtures.three_lead_raw;
  const bytes = base64ToUint8Array(f.bytes_b64);
  const frame = await protocolV2.unpackMultiChannelFrame(bytes);

  assert.equal(frame.header.activeChannelCount, 3);
  assert.deepEqual(frame.header.activeLeadNames, ["Lead-I", "Lead-II", "Lead-III"]);
  assert.deepEqual(frame.channels["Lead-I"], f.expected_samples[0]);
  assert.deepEqual(frame.channels["Lead-II"], f.expected_samples[1]);
  assert.deepEqual(frame.channels["Lead-III"], f.expected_samples[2]);
});

await runTest("Decode 6-Lead Limb Raw Synthetic Frame from Backend Encoder", async () => {
  const f = fixtures.six_lead_raw;
  const bytes = base64ToUint8Array(f.bytes_b64);
  const frame = await protocolV2.unpackMultiChannelFrame(bytes);

  assert.equal(frame.header.activeChannelCount, 6);
  assert.deepEqual(frame.header.activeLeadNames, [
    "Lead-I",
    "Lead-II",
    "Lead-III",
    "Lead-aVR",
    "Lead-aVL",
    "Lead-aVF",
  ]);
  for (let i = 0; i < 6; i++) {
    const lead = frame.header.activeLeadNames[i];
    assert.deepEqual(frame.channels[lead], f.expected_samples[i]);
  }
});

await runTest("Decode 12-Lead Complete Raw Synthetic Frame from Backend Encoder", async () => {
  const f = fixtures.twelve_lead_raw;
  const bytes = base64ToUint8Array(f.bytes_b64);
  const frame = await protocolV2.unpackMultiChannelFrame(bytes);

  assert.equal(frame.header.activeChannelCount, 12);
  assert.deepEqual(frame.header.activeLeadNames, protocolV2.LEAD_NAMES_ORDER);
  for (let i = 0; i < 12; i++) {
    const lead = protocolV2.LEAD_NAMES_ORDER[i];
    assert.deepEqual(frame.channels[lead], f.expected_samples[i]);
  }
});

await runTest("Decode 12-Lead Planar Delta-Zlib Frame with Sentinel Samples", async () => {
  const f = fixtures.twelve_lead_delta_zlib;
  const bytes = base64ToUint8Array(f.bytes_b64);
  const frame = await protocolV2.unpackMultiChannelFrame(bytes);

  assert.equal(frame.header.isCompressed, true);
  assert.equal(frame.header.activeChannelCount, 12);
  assert.equal(frame.header.leadOffMask, 0x0001);
  assert.equal(frame.header.clippingMask, 0x0002);
  assert.equal(frame.header.isLeadOff, true);
  assert.equal(frame.header.isClipped, true);

  // Check sentinel missing sample preserved in Lead-I index 10
  assert.equal(frame.channels["Lead-I"][10], -32768);

  // Check all channels match expected reconstructed samples
  for (let i = 0; i < 12; i++) {
    const lead = protocolV2.LEAD_NAMES_ORDER[i];
    assert.deepEqual(frame.channels[lead], f.expected_samples[i]);
  }
});

await runTest("Synchronous Unpack of Uncompressed Frame", async () => {
  const f = fixtures.twelve_lead_raw;
  const bytes = base64ToUint8Array(f.bytes_b64);
  const syncFrame = protocolV2.unpackMultiChannelFrameSync(bytes);
  assert.equal(syncFrame.header.activeChannelCount, 12);
  assert.equal(syncFrame.channels["Lead-I"].length, 10);
});

await runTest("Synchronous Unpack of Compressed Frame Throws Explicit Error", async () => {
  const f = fixtures.twelve_lead_delta_zlib;
  const bytes = base64ToUint8Array(f.bytes_b64);
  assert.throws(
    () => protocolV2.unpackMultiChannelFrameSync(bytes),
    (err) => err instanceof protocolV2.ProtocolV2Error && err.code === 4014
  );
});

// ------------------------------------------------------------------------------
// Test Group 2: Integrity & Malformed Frame Rejection
// ------------------------------------------------------------------------------

await runTest("Detect and Reject CRC-32 Checksum Corruption", async () => {
  const f = fixtures.three_lead_raw;
  const bytes = base64ToUint8Array(f.bytes_b64);
  // Corrupt payload byte
  bytes[bytes.length - 1] ^= 0xFF;

  await assert.rejects(
    async () => await protocolV2.unpackMultiChannelFrame(bytes),
    (err) => err instanceof protocolV2.ProtocolV2Error && err.code === 4006
  );
});

await runTest("Reject Truncated Frame Underflow (< 32 bytes)", async () => {
  const truncated = new Uint8Array(20);
  await assert.rejects(
    async () => await protocolV2.unpackMultiChannelFrame(truncated),
    (err) => err instanceof protocolV2.ProtocolV2Error && err.code === 4002
  );
});

await runTest("Reject Oversized Frame (> 64 KiB ceiling)", async () => {
  const oversized = new Uint8Array(65537);
  await assert.rejects(
    async () => await protocolV2.unpackMultiChannelFrame(oversized),
    (err) => err instanceof protocolV2.ProtocolV2Error && err.code === 4001
  );
});

