await runTest("Reject Invalid Active Leads Mask (zero or out-of-range)", async () => {
  const f = fixtures.single_lead_raw;
  const bytes = base64ToUint8Array(f.bytes_b64);
  // Zero active leads mask (bytes 18..19)
  bytes[18] = 0x00;
  bytes[19] = 0x00;

  await assert.rejects(
    async () => await protocolV2.unpackMultiChannelFrame(bytes),
    (err) => err instanceof protocolV2.ProtocolV2Error && err.code === 4010
  );
});

await runTest("Decompression Bomb Safety Protection", async () => {
  // Test decompressZlib with a tiny limit (10 bytes) against a stream that expands larger
  const f = fixtures.twelve_lead_delta_zlib;
  const bytes = base64ToUint8Array(f.bytes_b64);
  const { payload } = protocolV2.unpackMultiChannelHeader(bytes);

  await assert.rejects(
    async () => await protocolV2.decompressZlib(payload, 50),
    (err) => err instanceof protocolV2.ProtocolV2Error && err.code === 4011
  );
});

// ------------------------------------------------------------------------------
// Test Group 3: Backward Compatibility (Protocol v1 Single-Lead)
// ------------------------------------------------------------------------------

await runTest("Protocol v1 Single-Lead 28-Byte Decoder Remains Operational", async () => {
  // Construct a valid v1 28-byte frame
  const payload = new Uint8Array([100, 0, 200, 0]); // 2 int16 samples little-endian
  const payloadLen = payload.byteLength;
  const v1Frame = new Uint8Array(28 + payloadLen);
  const view = new DataView(v1Frame.buffer);

  view.setUint8(0, 0xCC); // magic
  view.setUint8(1, 0x01); // v1
  view.setUint8(2, 0x01); // MSG_TYPE_ECG_DATA
  view.setUint8(3, 0);    // flags
  view.setUint32(4, 10, false); // seq
  view.setBigUint64(8, 1700000000000n, false); // ts
  view.setUint16(16, 250, false); // rate
  view.setUint16(18, 1, false);   // channel_id
  view.setUint16(20, 2, false);   // sample_count
  view.setUint16(22, payloadLen, false); // payload_len

  const crc = protocolV1.computeCrc32(payload);
  view.setUint32(24, crc, false);
  v1Frame.set(payload, 28);

  const decoded = protocolV1.unpackTelemetryFrame(v1Frame.buffer);
  assert.equal(decoded.header.version, 1);
  assert.equal(decoded.header.sequenceNumber, 10);
  assert.equal(decoded.samples.length, 2);
  assert.equal(decoded.samples[0], 100);
  assert.equal(decoded.samples[1], 200);
});

// ------------------------------------------------------------------------------
// Test Group 4: CSRF Helper and Feature Flag Isolation
// ------------------------------------------------------------------------------

await runTest("CSRF Helper Safely Handles Non-Browser Environment", () => {
  assert.equal(csrfModule.getCsrfToken(), null);
  assert.deepEqual(csrfModule.getCsrfHeaders(), {});
  assert.throws(
    () => csrfModule.assertCsrfToken(),
    (err) => err instanceof csrfModule.CsrfError
  );
});

await runTest("Feature Flag Defaults to Disabled", () => {
  assert.equal(
    backendConfig.IS_MULTILEAD_ENABLED,
    false,
    "IS_MULTILEAD_ENABLED must default to false"
  );
});

// ------------------------------------------------------------------------------
// Test Group 5: F-01 Sample Retrieval Inner Payload Decoding & Error Safety
// ------------------------------------------------------------------------------

await runTest("Decode Raw Stored Inner Payload via decodeMultichannelRaw (F-01)", () => {
  // Extract pure raw sample payload (without 32-byte header) from fixture
  const f = fixtures.three_lead_raw;
  const fullBytes = base64ToUint8Array(f.bytes_b64);
  const innerPayload = fullBytes.subarray(32); // Strip 32-byte header

  const channels = protocolV2.decodeMultichannelRaw(innerPayload, 3, 3, true);
  assert.equal(channels.length, 3);
  assert.deepEqual(channels[0], f.expected_samples[0]);
  assert.deepEqual(channels[1], f.expected_samples[1]);
  assert.deepEqual(channels[2], f.expected_samples[2]);
});

await runTest("Decode Compressed Stored Inner Payload via decompressZlib and decodeMultichannelDelta (F-01)", async () => {
  // Extract pure delta-zlib payload (without 32-byte header) from fixture
  const f = fixtures.twelve_lead_delta_zlib;
  const fullBytes = base64ToUint8Array(f.bytes_b64);
  const innerPayload = fullBytes.subarray(32); // Strip 32-byte header

  const decompressed = await protocolV2.decompressZlib(innerPayload);
  const channels = protocolV2.decodeMultichannelDelta(decompressed, 12, 50, true);
  assert.equal(channels.length, 12);
  for (let i = 0; i < 12; i++) {
    assert.deepEqual(channels[i], f.expected_samples[i]);
  }
});

await runTest("Inner Payload Decoding Rejects Truncated / Corrupt Byte Length Safely", () => {
  const truncatedPayload = new Uint8Array(29); // Expected 3 channels * 5 samples * 2 bytes = 30 bytes
  assert.throws(
    () => protocolV2.decodeMultichannelRaw(truncatedPayload, 3, 5, true),
    (err) => err instanceof protocolV2.ProtocolV2Error && err.code === 4005
  );
});

await runTest("Simulate Hook Decoding Dispatcher Handling Stored Inner Payloads without Magic Byte Error", async () => {
  // Simulate API response from GET /api/v1/telemetry/recordings/{id}/chunks/{id}/samples
  const f = fixtures.twelve_lead_raw;
  const fullBytes = base64ToUint8Array(f.bytes_b64);
  const innerPayload = fullBytes.subarray(32);
  const payloadBase64 = Buffer.from(innerPayload).toString("base64");

  const mockApiResponse = {
    channelCount: 12,
    sampleCount: 10,
    compressionCodec: "raw",
    channelOrder: protocolV2.LEAD_NAMES_ORDER,
    payloadBase64,
  };

  // Run the exact decoding branch implemented in useMultiLeadRecording
  const payloadBytes = base64ToUint8Array(mockApiResponse.payloadBase64);
  let channelArrays;
  if (mockApiResponse.compressionCodec === "raw") {
    channelArrays = protocolV2.decodeMultichannelRaw(
      payloadBytes,
      mockApiResponse.channelCount,
      mockApiResponse.sampleCount,
      true
    );
  } else if (mockApiResponse.compressionCodec === "delta_zlib_planar") {
    const decompressed = await protocolV2.decompressZlib(payloadBytes);
    channelArrays = protocolV2.decodeMultichannelDelta(
      decompressed,
      mockApiResponse.channelCount,
      mockApiResponse.sampleCount,
      true
    );
  }

  assert.equal(channelArrays.length, 12);
  assert.deepEqual(channelArrays[0], f.expected_samples[0]);
});

console.log("================================================================================");
console.log(`Test Execution Finished: ${passedTests} passed, ${failedTests} failed.`);
console.log("================================================================================");

if (failedTests > 0) {
  process.exit(1);
}
